import sys

def solve():
    import sys
    import numpy as np

    def dfs(x, y, id):
        if x < 0 or x >= n or y < 0 or y >= m or grid[x][y] != '.':
            return
        grid[x][y] = str(id)
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            dfs(x + dx, y + dy, id)

    input = sys.stdin.read().split()
    n, m = map(int, input[:2])
    grid = [list(input[i]) for i in range(2, 2 + n)]

    id = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
                dfs(i, j, id)
                id += 1

    for i in range(n):
        for j in range(m):
            for dx, dy in [(-1, 0), (1, -1), (0, -1), (1, 0), (1, 1), (0, 1), (-1, 1), (-1, -1)]:
                nx, ny = i + dx, j + dy
                if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] != '#' and grid[nx][ny] != grid[i][j]:
                    break
            else:
                print(-1)
                return

    for row in grid:
        print(''.join(row))

solve()
